function downloadExcel(){if(!UI.rows.length)return;try{const wb=makeWorkbook(root.XLSX,UI.rows,UI.settings,{mamFile:UI.mamFile,mamSheet:UI.mamSheet,profileSource:UI.profiles&&UI.profiles.sourceFile,masterCount:UI.employees.length});root.XLSX.writeFile(wb,'ATPL_Mam_Compliance_'+(UI.settings.month||'Salary')+'.xlsx',{compression:true});setMessage('Updated Excel downloaded: Main + category + Bank + Statutory + Rule Audit + Review tabs.',false)}catch(e){setMessage('Excel download nahi ho paaya: '+(e.message||e),true)}}
